  var HDR_REG = [['contract', /^договор\s*\(|^номер/i], ['type', /^тип$/i], ['cp', /контрагент/i], ['subject', /предмет/i], ['sum', /сумма по договору|^сумма/i], ['paid', /^оплачено/i], ['shipped', /^отгружено/i], ['outcome', /^итог/i], ['status', /^статус/i], ['payments', /^платежи/i], ['notes', /замечан|расхожд|примеч/i], ['files', /^файлы$/i]];
